package org.jsoup.nodes;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.IOException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.TextNode;
import org.jsoup.nodes.LeafNode;
import org.jsoup.dom.Appendable;
import org.jsoup.parser.Document;
import org.jsoup.parser.Parser;
import org.jsoup.nodes.Document.OutputSettings;

public class TextNodeTest {

    @Test
    public void newNode() {
        // no exception should be thrown when creating a new Node with a null text
        assertNull(new TextNode(null));
    }

    @Test
    public void newNodeWithText() {
        String text = "Hello, World!";
        TextNode node = new TextNode(text);
        assertNotNull(node);
        assertEquals(text, node.text());
    }

    @Test
    public void nodeName() {
        TextNode node = new TextNode("example");
        assertEquals("text", node.nodeName());
    }

    @Test
    public void text() {
        String text = "Hello, World!";
        TextNode node = new TextNode(text);
        assertEquals(text, node.text());
    }

    @Test
    public void textWithNullText() {
        TextNode node = new TextNode(null);
        assertNull(node.text());
    }

    @Test
    public void textSet() {
        String newText = "New Example";
        TextNode node = new TextNode("Old Example");
        node.text(newText);
        assertEquals(newText, node.text());
    }

    @Test
    public void getWholeText() {
        String text = "Hello,\nWorld!";
        TextNode node = new TextNode(text);
        assertEquals(text, node.getWholeText());
    }

    @Test
    public void isBlank() {
        String text = "";
        TextNode node = new TextNode(text);
        assertTrue(node.isBlank());
    }

    @Test
    public void isNotBlank() {
        String text = "Hello";
        TextNode node = new TextNode(text);
        assertFalse(node.isBlank());
    }

    @Test
    public void splitText() throws IOException {
        TextNode node = new TextNode("Hello, World!");
        int offset = 7;
        TextNode newNode = node.splitText(offset);
        assertNotNull(newNode);
        assertEquals("World!", newNode.text());
    }

    @Test
    public void outerHtmlHead() throws IOException {
        Appendable accum = mock(Appendable.class);
        Document document = new Document();
        document.setDocumentParser(new Parser(document));
        TextNode node = new TextNode("example");
        String expectedHTML = "<text>Hello, World!</text>";
        node.outerHtmlHead(accum, 0, document.getOutputSettings());
        assertEquals(expectedHTML, accum.toString());
    }

    @Test
    public void outerHtmlTail() throws IOException {
        Appendable accum = mock(Appendable.class);
        Document document = new Document();
        document.setDocumentParser(new Parser(document));
        TextNode node = new TextNode("example");
        String expectedHTML = "<text>Hello, World!</text>";
        node.outerHtmlTail(accum, 0, document.getOutputSettings());
        assertEquals(expectedHTML, accum.toString());
    }

    @Test
    public void toString() {
        TextNode node = new TextNode("Hello, World!");
        assertNotNull(node.toString());
        assertTrue(node.toString().contains("Hello, World!"));
    }

    @Test
    public void clone() {
        TextNode node = new TextNode("example");
        TextNode clonedNode = node.clone();
        assertNotNull(clonedNode);
        assertEquals("example", clonedNode.text());
    }

    @Test
    public void createFromEncoded() throws IOException {
        String encodedText = "Hello, World!";
        TextNode node = TextNode.createFromEncoded(encodedText);
        assertNotNull(node);
        assertEquals(encodedText, node.text());
    }

    @Test
    public void normaliseWhitespace() {
        String text = "\t\n  ";
        String expectedNormalised = StringUtil.normaliseWhitespace(text);
        assertEquals(expectedNormalised, TextNode.normaliseWhitespace(text));
    }

    @Test
    public void stripLeadingWhitespace() {
        String text = "Hello,\nWorld!";
        String expectedStriped = TextNode.stripLeadingWhitespace(text);
        assertEquals(expectedStriped, TextNode.stripLeadingWhitespace(text));
    }

    @Test
    public void lastCharIsWhitespace() {
        StringBuilder sb = mock(StringBuilder.class);
        assertTrue(TextNode.lastCharIsWhitespace(sb));
        assertFalse(TextNode.lastCharIsWhitespace(sb.append('A')));
    }
}
